    public void new(Name _name, Name _label, Description _desc, ResourceName _iconName = resourceStr(TFMMissingImage), boolean _mainMenuEnabled = true, boolean _contextMenuEabled = true, container _categories = conNull(), boolean _oneClickSetup = false)
    {
